segments.data:
[
  {
    "id": "S00",
    "title": "Pinned Baseline and Architecture Decisions",
    "dependencies": [],
    "goal": "Create a reproducible writable fork baseline and freeze decisions required by every later section."
  },
  {
    "id": "S01",
    "title": "Host Strangler Seam and Parity",
    "dependencies": [
      "S00"
    ],
    "goal": "Insert a provider-neutral ConversationHostAdapter without changing supported behavior."
  },
  {
    "id": "S02",
    "title": "Authoritative State, Outbox, Durable Jobs, and Bounded Workers",
    "dependencies": [
      "S01"
    ],
    "goal": "Make run state, event delivery, and continuation durable without creating a second authority."
  },
  {
    "id": "S03",
    "title": "Repository Inventory, Watching, Exact Search, and Overlay Indexes",
    "dependencies": [
      "S02"
    ],
    "goal": "Make large repositories explorable without placing entire projects into model context."
  },
  {
    "id": "S04",
    "title": "Symbols, Structural Search, Dependency Graph, and Optional Large-Repo Engines",
    "dependencies": [
      "S03"
    ],
    "goal": "Add precise code intelligence with graceful degradation."
  },
  {
    "id": "S05",
    "title": "Retrieval Planner, Context Packs, Context Ledger, and Repository Map",
    "dependencies": [
      "S04"
    ],
    "goal": "Deliver small, relevant, versioned context to each model role."
  },
  {
    "id": "S06",
    "title": "Prompt Compiler, Requirements, Evidence Matrix, and Independent Judges",
    "dependencies": [
      "S05"
    ],
    "goal": "Isolate roles and make completion evidence enforceable."
  },
  {
    "id": "S07",
    "title": "Tool Broker, Sidecar Protocols, Egress, and Secret Scanning",
    "dependencies": [
      "S06"
    ],
    "goal": "Create one controlled gateway for reads, mutations, external binaries, and outbound data."
  },
  {
    "id": "S08",
    "title": "Git Runtime, External Worktrees, Atomic Edits, and Diff Review",
    "dependencies": [
      "S07"
    ],
    "goal": "Make every code mutation isolated, hash-gated, reviewable, and recoverable."
  },
  {
    "id": "S09",
    "title": "Native Windows Sandbox, Process Runtime, and Terminal",
    "dependencies": [
      "S08"
    ],
    "goal": "Run commands under explicit, testable Windows containment."
  },
  {
    "id": "S10",
    "title": "Dashboard Vertical Slice and Secure Local Transport",
    "dependencies": [
      "S09"
    ],
    "goal": "Expose authoritative run, context, diff, terminal, evidence, recovery, and security state."
  },
  {
    "id": "S11",
    "title": "ChatGPT Companion, WXT Extension, Native Messaging, and MCP",
    "dependencies": [
      "S10"
    ],
    "goal": "Link normal ChatGPT conversations to local runs while preserving honest capability boundaries."
  },
  {
    "id": "S12",
    "title": "OpenAI API Native Host, Automatic Continuation, and Application-Managed Agents",
    "dependencies": [
      "S10",
      "S06",
      "S08"
    ],
    "goal": "Provide native hosted agent mode with controlled continuation and scoped agents."
  },
  {
    "id": "S13",
    "title": "Browser Automation and Windows UI Automation",
    "dependencies": [
      "S09",
      "S10"
    ],
    "goal": "Add controlled browser and desktop interaction without expanding the privileged renderer."
  },
  {
    "id": "S14",
    "title": "Reliability, Chaos, Supply Chain, Migration, and Updates",
    "dependencies": [
      "S02",
      "S03",
      "S07",
      "S08",
      "S09",
      "S11",
      "S12",
      "S13"
    ],
    "goal": "Prove survival under faults, upgrades, corruption, sidecar failures, and security incidents."
  },
  {
    "id": "S15",
    "title": "Release Candidate, Benchmarks, Documentation, and Old-Code Removal",
    "dependencies": [
      "S14"
    ],
    "goal": "Produce the first signed Windows 11 x64 release and remove obsolete paths only after proven replacement."
  }
]
